if ($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf(); $username=trim($_POST['username']??''); $password=$_POST['password']??''; if($username===''||$password==='') $error='Enter your username and password.'; else { $stmt=$conn->prepare('SELECT user_id,full_name,username,email,password_hash,role,student_id FROM app_users WHERE username=? OR email=? LIMIT 1'); $stmt->bind_param('ss',$username,$username); $stmt->execute(); $u=$stmt->get_result()->fetch_assoc(); if($u && password_verify($password,$u['password_hash'])) { session_regenerate_id(true); unset($u['password_hash']); $_SESSION['user']=$u; header('Location: index.php'); exit; } $error='Invalid username/email or password.'; } }
$pageTitle='Sign in'; require 'includes/header.php'; ?>
<div class="login-page"><div class="card login-card"><div class="brand-mark" style="display:inline-block;margin-bottom:18px">MIU</div><h1>Welcome back</h1><p class="subheading">Sign in to the student management portal.</p><?php if($error): ?><div class="alert error"><?= e($error) ?></div><?php endif; ?><form method="post" autocomplete="on"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><div class="field"><label for="username">Username or email</label><input id="username" name="username" required maxlength="120" autocomplete="username" placeholder="Enter username or email"></div><div class="field"><label for="password">Password</label><input id="password" type="password" name="password" required autocomplete="current-password" placeholder="Enter your password"></div><button class="btn" type="submit" style="width:100%">Sign in securely</button></form><p class="hint" style="margin-top:18px">First time? Run <code>setup_admin.php</code> once as described in README, then remove that setup file.</p></div></div><?php require 'includes/footer.php'; ?>